[
  {
    "text": "PalmClaw is an open-source agent framework that runs natively on mobile phones, managing sessions, memory, skills, tools, and the agent loop directly on the device.",
    "topic": "PalmClaw framework"
  },
  {
    "text": "PalmClaw exposes device capabilities as device tools with explicit arguments, structured results, and clearly defined execution boundaries, enabling agents to use mobile capabilities directly.",
    "topic": "PalmClaw device tools"
  },
  {
    "text": "Existing mobile agents primarily operate smartphones through graphical user interface (GUI) actions such as tapping, swiping, and typing, which form long, interface-dependent sequences and cannot directly access device capabilities.",
    "topic": "Limitations of existing mobile agents"
  },
  {
    "text": "PalmClaw keeps each action explicit and controlled by defining clear execution boundaries for device tools.",
    "topic": "Execution boundaries in PalmClaw"
  },
  {
    "text": "PalmClaw enables agents to use mobile device sensors and daily-use applications directly, leveraging the device's data and capabilities.",
    "topic": "Mobile device integration in PalmClaw"
  }
]
